svg.g:
{%- for l in m.provincias %}
  {{ l.nome }}: {{ l.valor }} {{ rotulo }} em {{ l.mencoes }} publicações
{%- endfor %}
{%- for l in m.provincias %}{% if l.mencoes %}
  {{ l.codigo }}
  {%- if l.variacao %}
  {{ '▲ +' if l.variacao > 0 else '▼ −' }}{{ l.variacao|abs }}
  {%- endif %}
{%- endif %}{% endfor %}
